gameActivityImportAdditions.insert:
import com.google.android.gms.ads.MobileAds;
import com.google.android.gms.ads.initialization.InitializationStatus;
import com.google.android.gms.ads.initialization.OnInitializationCompleteListener;
import com.google.android.gms.ads.AdRequest;
import com.google.android.gms.ads.LoadAdError;
import com.google.android.gms.ads.FullScreenContentCallback;
import com.google.android.gms.ads.AdError;
import com.google.android.gms.ads.interstitial.InterstitialAd;
import com.google.android.gms.ads.interstitial.InterstitialAdLoadCallback;
import androidx.annotation.NonNull;
import android.util.Log;

gameActivityClassAdditions.insert:
private InterstitialAd mInterstitialAd;
private String mOyunKafasiAdUnitId;
private boolean mOyunKafasiAdMobInitialized = false;
private boolean mOyunKafasiAdLoading = false;

private void OyunKafasi_LoadInterstitial() {
    if (mOyunKafasiAdUnitId == null || mOyunKafasiAdUnitId.isEmpty()) {
        android.util.Log.e("OyunKafasi", "Interstitial Ad Unit ID is empty.");
        return;
    }

    if (mOyunKafasiAdLoading || mInterstitialAd != null) {
        return;
    }

    mOyunKafasiAdLoading = true;
    AdRequest adRequest = new AdRequest.Builder().build();

    InterstitialAd.load(_activity, mOyunKafasiAdUnitId, adRequest,
        new InterstitialAdLoadCallback() {
            @Override
            public void onAdLoaded(@NonNull InterstitialAd interstitialAd) {
                mOyunKafasiAdLoading = false;
                mInterstitialAd = interstitialAd;
                android.util.Log.i("OyunKafasi", "Interstitial Ad Loaded Successfully.");
            }

            @Override
            public void onAdFailedToLoad(@NonNull LoadAdError loadAdError) {
                mOyunKafasiAdLoading = false;
                mInterstitialAd = null;
                android.util.Log.e("OyunKafasi", "Failed to load Interstitial Ad: " + loadAdError.getMessage());
            }
        });
}

public void AndroidThunkJava_InitAdMob(final String adUnitId) {
    _activity.runOnUiThread(new Runnable() {
        @Override
        public void run() {
            mOyunKafasiAdUnitId = adUnitId;

            if (mOyunKafasiAdMobInitialized) {
                OyunKafasi_LoadInterstitial();
                return;
            }

            MobileAds.initialize(_activity, new OnInitializationCompleteListener() {
                @Override
                public void onInitializationComplete(InitializationStatus initializationStatus) {
                    mOyunKafasiAdMobInitialized = true;
                    android.util.Log.d("OyunKafasi", "AdMob Initialized.");
                    OyunKafasi_LoadInterstitial();
                }
            });
        }
    });
}

public boolean AndroidThunkJava_IsInterstitialReady() {
    return mInterstitialAd != null;
}

public void AndroidThunkJava_ShowInterstitial() {
    _activity.runOnUiThread(new Runnable() {
        @Override
        public void run() {
            if (mInterstitialAd == null) {
                android.util.Log.d("OyunKafasi", "Interstitial Ad is not ready yet.");
                return;
            }

            final InterstitialAd adToShow = mInterstitialAd;
            mInterstitialAd = null;

            adToShow.setFullScreenContentCallback(new FullScreenContentCallback() {
                @Override
                public void onAdShowedFullScreenContent() {
                    android.util.Log.d("OyunKafasi", "Interstitial Ad showed.");
                }

                @Override
                public void onAdDismissedFullScreenContent() {
                    android.util.Log.d("OyunKafasi", "Interstitial Ad dismissed. Loading the next ad.");
                    OyunKafasi_LoadInterstitial();
                }

                @Override
                public void onAdFailedToShowFullScreenContent(@NonNull AdError adError) {
                    android.util.Log.e("OyunKafasi", "Failed to show Interstitial Ad: " + adError.getMessage());
                    OyunKafasi_LoadInterstitial();
                }
            });

            adToShow.show(_activity);
        }
    });
}
